    for (auto &row : a)
        for (int &x : row) cin >> x;
    // dp[c]: smallest total cost of a path ending at column c of the current row.
    vector<int> dp(a[0], a[0] + 4);
    for (int r = 1; r < 4; r++) {
        vector<int> nd(4);
        for (int c = 0; c < 4; c++) {
