import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int[][] a = new int[4][4];
        for (int r = 0; r < 4; r++)
            for (int c = 0; c < 4; c++) a[r][c] = nextInt();
        int[] dp = a[0].clone();
        for (int r = 1; r < 4; r++) {
            int[] nd = new int[4];
            for (int c = 0; c < 4; c++) {
                int best = Integer.MAX_VALUE;
                for (int k = Math.max(0, c - 1); k <= Math.min(3, c + 1); k++) best = Math.min(best, dp[k]);
                nd[c] = a[r][c] + best;
            }
            dp = nd;
        }
        System.out.println(100 - Arrays.stream(dp).min().getAsInt());
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"slices"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	var a [4][4]int
	for r := range a {
		for c := range a[r] {
			a[r][c] = nextInt()
		}
	}
	dp := a[0]
	for r := 1; r < 4; r++ {
		var nd [4]int
		for c := 0; c < 4; c++ {
			best := dp[c]
			for k := max(0, c-1); k <= min(3, c+1); k++ {
				best = min(best, dp[k])
			}
			nd[c] = a[r][c] + best
		}
		dp = nd
	}
	fmt.Println(100 - slices.Min(dp[:]))
}
